$ cat StackPer.java
public class StackPer {
    static int d = 0;
    static void deep() { d++; deep(); }
    public static void main(String[] a) throws Exception {
        Thread t = new Thread(() -> {
            try { deep(); }
            catch (StackOverflowError so) {
                System.out.println("  [worker] StackOverflowError, depth=" + d);
            }
        }, "worker");
        t.start(); t.join();
        System.out.println("  [main] 워커가 죽었는데 나는 산다");

        Thread u = new Thread(() -> deep(), "worker-2");   // 안 잡는다
        u.setUncaughtExceptionHandler((th, e) ->
            System.out.println("  [handler] " + th.getName() + " -> " + e.getClass().getName()));
        u.start(); u.join();
        System.out.println("  [main] 여전히 산다. 프로세스는 안 죽었다");
    }
}

